#requires -Version 5.1
[CmdletBinding()]
param([string]$ProjectRoot = (Get-Location).Path)

$ErrorActionPreference = "Stop"
$root = [IO.Path]::GetFullPath($ProjectRoot)
if (-not (Test-Path -LiteralPath (Join-Path $root "project.godot") -PathType Leaf)) {
    throw "project.godot nao encontrado. Execute este arquivo na raiz do projeto."
}

$files = @(
    @{ Relative = "scripts\hit_music_r7\playfield_renderer.gd"; Data = "" },
    @{ Relative = "scripts\hit_music_r7\stage.gd"; Data = "" }
)

$backupRoot = Join-Path $root ("backup-r13-emocao-" + (Get-Date -Format "yyyyMMdd-HHmmss"))
New-Item -ItemType Directory -Path $backupRoot -Force | Out-Null

foreach ($item in $files) {
    $target = Join-Path $root $item.Relative
    if (-not (Test-Path -LiteralPath $target -PathType Leaf)) {
        throw "Arquivo esperado nao encontrado: $($item.Relative)"
    }
    $backup = Join-Path $backupRoot $item.Relative
    New-Item -ItemType Directory -Path (Split-Path -Parent $backup) -Force | Out-Null
    Copy-Item -LiteralPath $target -Destination $backup -Force
}

try {
    foreach ($item in $files) {
        [IO.File]::WriteAllBytes(
            (Join-Path $root $item.Relative),
            [Convert]::FromBase64String($item.Data)
        )
    }
}
catch {
    foreach ($item in $files) {
        $backup = Join-Path $backupRoot $item.Relative
        if (Test-Path -LiteralPath $backup) {
            Copy-Item -LiteralPath $backup -Destination (Join-Path $root $item.Relative) -Force
        }
    }
    throw "Falha ao atualizar; os originais foram restaurados. $($_.Exception.Message)"
}

Write-Host ""
Write-Host "HIT MUSIC R13 EMOCAO aplicado." -ForegroundColor Green
Write-Host "Backup: $backupRoot" -ForegroundColor Yellow
Write-Host ""
Write-Host " - hold fino, moderno e mais legivel"
Write-Host " - MP3 correto de cada cenario no Master, com fallback do video"
Write-Host " - bolinhas e aneis reagem a acertos e combo"
Write-Host " - Carmine com resposta visual reforcada"
Write-Host " - animacao deterministica para manter FPS estavel"
Write-Host ""
Write-Host "Abra project.godot e teste Carmine primeiro." -ForegroundColor Cyan

